@MainActor
final class Counter {
    var count = 5
    func bump() { count += 1 }
}

nonisolated func readValue() async -> Int {
    10
}

@MainActor
func run() async {
    let c = Counter()
    let extra = await readValue()
    c.bump()
    let total = c.count + extra
    print("Total: \(total)")
}

await run()

