@MainActor
final class LogCollector {
    var logs: [String] = []

    func addLog(_ text: String) {
        logs.append(text)
    }
}

nonisolated func generateTimestamp() -> String {
    "12:00:00"
}

@MainActor
func testLog() {
    let collector = LogCollector()
    let stamp = generateTimestamp()
    collector.addLog(stamp)
    print("Logged: \(collector.logs.first ?? "")")
}

testLog()

