@MainActor
final class ScoreKeeper {
    var score: Int = 10

    nonisolated func calculateBonus(points: Int) -> Int {
        points * 3
    }

    func applyBonus() {
        let bonus = calculateBonus(points: 5)
        score += bonus
        print("Final Score: \(score)")
    }
}

@MainActor
func runScoreTest() {
    let keeper = ScoreKeeper()
    keeper.applyBonus()
}

runScoreTest()
